### Configuration Examples

**Example 1: ASP.NET Core Integration (Code-First Generation)**

```csharp
// Program.cs
var builder = WebApplication.CreateBuilder(args);

// Add OpenAPI generation
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new OpenApiInfo
    {
        Title = "Gainwell Claims API",
        Version = "v1",
        Description = "Claims submission and management API",
        Contact = new OpenApiContact
        {
            Name = "API Support",
            Email = "api-support@gainwell.com"
        }
    });

    // Include XML comments
    var xmlFile = $"{Assembly.GetExecutingAssembly().GetName().Name}.xml";
    var xmlPath = Path.Combine(AppContext.BaseDirectory, xmlFile);
    options.IncludeXmlComments(xmlPath);

    // Add security definition
    options.AddSecurityDefinition("oauth2", new OpenApiSecurityScheme
    {
        Type = SecuritySchemeType.OAuth2,
        Flows = new OpenApiOAuthFlows
        {
            ClientCredentials = new OpenApiOAuthFlow
            {
                TokenUrl = new Uri("https://auth.gainwell.com/oauth/token"),
                Scopes = new Dictionary<string, string>
                {
                    { "claims:read", "Read claims" },
                    { "claims:write", "Submit claims" }
                }
            }
        }
    });
});

var app = builder.Build();

// Enable Swagger UI
if (app.Environment.IsDevelopment() || app.Environment.IsStaging())
{
    app.UseSwagger();
    app.UseSwaggerUI(options =>
    {
        options.SwaggerEndpoint("/swagger/v1/swagger.json", "Claims API v1");
        options.RoutePrefix = "api-docs";
    });
}

app.Run();
```

